// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createCollection, createLink, createHighlight, deleteHighlight, deleteLink, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Request Body
    const collectionsPostRequestBody: string = `{
        "name": "Highlights Delete Lifecycle"
    }`;

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "id": 611
        },
        "name": "Highlights Delete Source",
        "tags": [],
        "type": "url",
        "url": "https://example.com/hl-delete"
    }`;

    // Request Body
    const highlightsPostRequestBody: string = `{
        "color": "green",
        "comment": "delete me",
        "endOffset": 17,
        "linkId": 622,
        "startOffset": 0,
        "text": "Deletable passage"
    }`;

    const collectionsPostResponse = await createCollection(client, URL_localhost, headers, collectionsPostRequestBody);
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    const linksPostResponse = await createLink(client, URL_localhost, headers, linksPostRequestBody, {"collection.id": getResponseValue(collectionsPostResponse, "response.id")});
    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    const highlightsPostResponse = await createHighlight(client, URL_localhost, headers, highlightsPostRequestBody, {"linkId": getResponseValue(linksPostResponse, "response.id")});
    expect(highlightsPostResponse.statusCode, 'status code').toBe(200);
    const highlightId = getResponseValue(highlightsPostResponse, "response.id");
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'collection name').toBe("Highlights Delete Lifecycle");
    expect(getResponseValue(linksPostResponse, "response.name"), 'link name').toBe("Highlights Delete Source");
    expect(getResponseValue(highlightsPostResponse, "response.color"), 'created colour').toBe("green");
    expect(getResponseValue(highlightsPostResponse, "response.comment"), 'created comment').toBe("delete me");
    expect(getResponseValue(highlightsPostResponse, "response.text"), 'created text').toBe("Deletable passage");

    const highlightsHighlightsDeleteResponse = await deleteHighlight(client, URL_localhost, headers, highlightId);
    expect(highlightsHighlightsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsHighlightsDeleteResponse, "response"), 'the deleted id comes back').toBe(highlightId);

    const highlightsHighlightsDelete1Response = await deleteHighlight(client, URL_localhost, headers, highlightId, 404);
    expect(highlightsHighlightsDelete1Response.statusCode, 'status code').toBe(404);
    expect(getResponseValue(highlightsHighlightsDelete1Response, "response"), 'a highlight that is already gone is not found').toBe("Highlight not found.");

    const abcDeleteResponse = await deleteHighlight(client, URL_localhost, headers, "abc", 400);
    expect(abcDeleteResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(abcDeleteResponse, "response"), 'an id that is not a number').toBe("Please choose a valid highlight.");

    const linksLinksDeleteResponse = await deleteLink(client, URL_localhost, headers, getResponseValue(linksPostResponse, "response.id"));
    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'deleted link').toBe(getResponseValue(linksPostResponse, "response.id"));
    const collectionsCollectionsDeleteResponse = await deleteCollection(client, URL_localhost, headers, getResponseValue(collectionsPostResponse, "response.id"));
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
});
